 78	    /**
 79	     * Move the animal according to the current weather and nearby food.
 80	     * @param simulator The simulator.
 81	     */
 82	    private void move(Simulator simulator)
 83	    {
 84	        Location newLocation = null;
 85	        switch(simulator.getWeather()){
 86	            case SUNNY:
 87	                newLocation = findFood(getSunnyFindingFoodProbability());
 88	                break;
 89	            case RAINY:
 90	                newLocation = findFood(getRainyFindingFoodProbability());
 91	                break;
 92	            case FOGGY:
 93	                newLocation = findFood(getFoggyFindingFoodProbability());
 94	                break;
 95	            default:
 96	                findFood(getRandom().nextDouble());
 97	                break;
 98	        }
 99	        if(newLocation == null) { 
100	            // No food found - try to move to a free location.
101	            newLocation = getField().freeAdjacentLocation(getLocation());
102	        }
103	        if(newLocation != null) {
104	            setLocation(newLocation);
105	        }
106	        else {
107	            // Overcrowding.
108	            setDead();
109	        }
110	    }
